+func TestShapeIndexEncodeWithoutBuild(t *testing.T) {
+	index := NewShapeIndex()
+	for i := 0; i < 20; i++ {
+		index.Add(RegularLoop(randomPoint(), s1.Degree*10, 50))
+	}
+	// Encode before any explicit Build.
+	var buf bytes.Buffer
+	if err := index.Encode(&buf); err != nil {
+		t.Fatal(err)
+	}
+	got := NewShapeIndex()
+	if err := got.Decode(&buf); err != nil {
+		t.Fatal(err)
+	}
+	checkShapeIndexEqual(t, got, index)
+	if len(got.cells) == 0 {
+		t.Errorf("decoded index has no cells")
+	}
+}
+
+func TestShapeIndexEncodePreservesShapeIDs(t *testing.T) {
+	index := NewShapeIndex()
+	a := makePolyline("0:0, 1:1")
+	b := makePolyline("2:2, 3:3")
+	c := makePolyline("4:4, 5:5")
+	index.Add(a)
+	index.Add(b)
+	index.Add(c)
+	index.Remove(b)
+
+	got := roundTripShapeIndex(t, index)
+	checkShapeIndexEqual(t, got, index)
+	if got.Shape(1) != nil || got.Shape(2) == nil {
+		t.Errorf("shape IDs not preserved")
+	}
+}
+
+func TestShapeIndexEncodeZeroEdgeShapes(t *testing.T) {
+	empty := PointVector{}
+	index := NewShapeIndex()
+	index.Add(&empty)
+	index.Add(LaxPolylineFromPoints(nil))
+	index.Add(LaxPolygonFromPoints(nil))
+	index.Add(LaxPolygonFromPoints([][]Point{{}}))
+	index.Add(&Polyline{})
+	index.Add(&edgeVectorShape{})
+	got := roundTripShapeIndex(t, index)
+	checkShapeIndexEqual(t, got, index)
+}
+
+func TestShapeIndexEncodeLargeRandom(t *testing.T) {
+	index := NewShapeIndex()
+	pts := make(PointVector, 2000)
+	for i := range pts {
+		pts[i] = randomPoint()
+	}
+	index.Add(&pts)
+	index.Add(RegularLoop(randomPoint(), s1.Degree*30, 3000))
+	got := roundTripShapeIndex(t, index)
+	checkShapeIndexEqual(t, got, index)
+}
+
+func encodedTestIndex(t *testing.T) []byte {
+	index := NewShapeIndex()
+	index.Add(makePolygon("0:0, 0:10, 10:10, 10:0; 2:2, 8:2, 8:8, 2:8", true))
+	index.Add(makePolyline("-10:-10, -20:-20, -30:-10"))
+	index.Add(makeLaxPolygon("60:60, 60:70, 70:70; 62:62, 64:62, 64:64"))
+	evs := &edgeVectorShape{}
+	evs.Add(parsePoint("5:5"), parsePoint("6:6"))
+	index.Add(evs)
+	var buf bytes.Buffer
+	if err := index.Encode(&buf); err != nil {
+		t.Fatal(err)
+	}
+	return buf.Bytes()
+}
+
+func TestShapeIndexDecodeTruncated(t *testing.T) {
+	data := encodedTestIndex(t)
+	for i := 0; i < len(data); i++ {
+		if err := NewShapeIndex().Decode(bytes.NewReader(data[:i])); err == nil {
+			t.Errorf("Decode of %d/%d bytes succeeded", i, len(data))
+		}
+	}
+}
+
+func TestShapeIndexDecodeCorrupted(t *testing.T) {
+	data := encodedTestIndex(t)
+	for i := range data {
+		for _, v := range []byte{0x00, 0xff, data[i] ^ 0x01, data[i] ^ 0x80} {
+			c := append([]byte(nil), data...)
+			c[i] = v
+			func() {
+				defer func() {
+					if r := recover(); r != nil {
+						t.Fatalf("Decode panicked with byte %d = %#x: %v", i, v, r)
+					}
+				}()
+				index := NewShapeIndex()
+				if index.Decode(bytes.NewReader(c)) == nil {
+					// If decoding succeeds the result must be usable.
+					for it := index.Iterator(); !it.Done(); it.Next() {
+					}
+				}
+			}()
+		}
+	}
+}
+
+func TestShapeIndexDecodeOversized(t *testing.T) {
+	huge := binary.AppendUvarint(nil, 1<<62)
+	tests := map[string][]byte{
+		"empty":    {},
+		"version":  {99},
+		"nextID":   append([]byte{1, 10}, huge...),
+		"numShape": append([]byte{1, 10, 5}, huge...),
+		// One polyline shape claiming an enormous number of vertices.
+		"vertices": append([]byte{1, 10, 1, 1, 0, byte(shapeIndexTagPolyline)}, binary.AppendUvarint(nil, maxEncodedVertices)...),
+		"numCells": append([]byte{1, 10, 0, 0}, huge...),
+		"cells":    append([]byte{1, 10, 0, 0}, binary.AppendUvarint(nil, maxEncodedCells)...),
+	}
+	for name, data := range tests {
+		if err := NewShapeIndex().Decode(bytes.NewReader(data)); err == nil {
+			t.Errorf("%s: Decode succeeded, want error", name)
+		}
+	}
+}
+
+func TestShapeIndexEncodeRemovedAfterBuild(t *testing.T) {
+	index := NewShapeIndex()
+	a := makePolyline("0:0, 1:1")
+	b := makePolyline("0:0, 1:1")
+	index.Add(a)
+	index.Add(b)
+	index.Build()
+	index.Remove(b)
+
+	got := roundTripShapeIndex(t, index)
+	if got.Shape(0) == nil || got.Shape(1) != nil {
+		t.Fatalf("shape IDs not preserved")
+	}
+	for it := got.Iterator(); !it.Done(); it.Next() {
+		for _, c := range it.IndexCell().shapes {
+			if got.Shape(c.shapeID) == nil {
+				t.Errorf("cell %v references removed shape %d", it.CellID(), c.shapeID)
+			}
+		}
+	}
+}

